export interface Query {
  /** query user did doc */
  Did(request: QueryDid): Promise<QueryDidResponse>;
  DidInfo(request: QueryDidInfo): Promise<QueryDidInfoResponse>;
  DidInfos(request: QueryDidInfos): Promise<QueryDidInfosResponse>;
  DidDocument(request: QueryDidDocument): Promise<QueryDidDocumentResponse>;
  Service(request: QueryService): Promise<QueryServiceResponse>;
  Services(request: QueryServices): Promise<QueryServicesResponse>;
  Credential(request: QueryCredential): Promise<QueryCredentialResponse>;
  Credentials(request: QueryCredentials): Promise<QueryCredentialsResponse>;
}

export const QueryServiceName = "metaearth.did.Query";
export class QueryClientImpl implements Query {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || QueryServiceName;
    this.rpc = rpc;
    this.Did = this.Did.bind(this);
    this.DidInfo = this.DidInfo.bind(this);
    this.DidInfos = this.DidInfos.bind(this);
    this.DidDocument = this.DidDocument.bind(this);
    this.Service = this.Service.bind(this);
    this.Services = this.Services.bind(this);
    this.Credential = this.Credential.bind(this);
    this.Credentials = this.Credentials.bind(this);
  }
  Did(request: QueryDid): Promise<QueryDidResponse> {
    const data = QueryDid.encode(request).finish();
    const promise = this.rpc.request(this.service, "Did", data);
    return promise.then((data) => QueryDidResponse.decode(new BinaryReader(data)));
  }

  DidInfo(request: QueryDidInfo): Promise<QueryDidInfoResponse> {
    const data = QueryDidInfo.encode(request).finish();
    const promise = this.rpc.request(this.service, "DidInfo", data);
    return promise.then((data) => QueryDidInfoResponse.decode(new BinaryReader(data)));
  }

  DidInfos(request: QueryDidInfos): Promise<QueryDidInfosResponse> {
    const data = QueryDidInfos.encode(request).finish();
    const promise = this.rpc.request(this.service, "DidInfos", data);
    return promise.then((data) => QueryDidInfosResponse.decode(new BinaryReader(data)));
  }

  DidDocument(request: QueryDidDocument): Promise<QueryDidDocumentResponse> {
    const data = QueryDidDocument.encode(request).finish();
    const promise = this.rpc.request(this.service, "DidDocument", data);
    return promise.then((data) => QueryDidDocumentResponse.decode(new BinaryReader(data)));
  }

  Service(request: QueryService): Promise<QueryServiceResponse> {
    const data = QueryService.encode(request).finish();
    const promise = this.rpc.request(this.service, "Service", data);
    return promise.then((data) => QueryServiceResponse.decode(new BinaryReader(data)));
  }

  Services(request: QueryServices): Promise<QueryServicesResponse> {
    const data = QueryServices.encode(request).finish();
    const promise = this.rpc.request(this.service, "Services", data);
    return promise.then((data) => QueryServicesResponse.decode(new BinaryReader(data)));
  }

  Credential(request: QueryCredential): Promise<QueryCredentialResponse> {
    const data = QueryCredential.encode(request).finish();
    const promise = this.rpc.request(this.service, "Credential", data);
    return promise.then((data) => QueryCredentialResponse.decode(new BinaryReader(data)));
  }

  Credentials(request: QueryCredentials): Promise<QueryCredentialsResponse> {
    const data = QueryCredentials.encode(request).finish();
    const promise = this.rpc.request(this.service, "Credentials", data);
    return promise.then((data) => QueryCredentialsResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
}

function bytesFromBase64(b64: string): Uint8Array {
  if ((globalThis as any).Buffer) {
    return Uint8Array.from((globalThis as any).Buffer.from(b64, "base64"));
  } else {
    const bin = globalThis.atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; ++i) {
      arr[i] = bin.charCodeAt(i);
    }
    return arr;
  }
}

function base64FromBytes(arr: Uint8Array): string {
  if ((globalThis as any).Buffer) {
    return (globalThis as any).Buffer.from(arr).toString("base64");
  } else {
    const bin: string[] = [];
    arr.forEach((byte) => {
      bin.push(globalThis.String.fromCharCode(byte));
    });
    return globalThis.btoa(bin.join(""));
  }
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
